{
  "scenes": [
    {
      "source": "S3",
      "mode": "explain",
      "narration": "Integral calculus gives us a more complete formulation of kinematics.",
      "focus": "Integral calculus gives us a more complete formulation"
    },
    {
      "source": "S1",
      "mode": "explain",
      "narration": "Since the time derivative of the velocity function is acceleration, we can take the indefinite integral of both sides.",
      "focus": "time derivative of the velocity function is acceleration"
    },
    {
      "source": "S6",
      "mode": "explain",
      "narration": "As shown in the velocity and position graphs, at time six point three seconds the velocity is zero and the boat has stopped.",
